// MOCK order lookup for DEMO — replace with a real HTTP Request node later.
// Optional webhook body fields for testing:
//   order_id: 'ORD-9999' -> duplicate order
//   demo_scenario: normal | delayed | lost | damaged | failed | returned | unknown_status | stuck
//                  | out_of_stock | invalid_status | total_mismatch | payment_mismatch
//                  | warehouse_discrepancy | warehouse_damaged | warehouse_missing | warehouse_stuck
const body = $json.body || {};
const orderId = body.order_id || 'ORD-1001';
const scenario = body.demo_scenario || 'normal';
const order = {
  id: orderId,
  customer: { id: 'CUST-55', name: 'Jane Doe', email: 'maya.zahrouni@gmail.com' },
  shipping_address: { street: '123 Market Street', city: 'Lisbon', postal_code: '1100-001', country: 'PT' },
  products: [
    { sku: 'SKU-1', name: 'Wireless Headphones', qty: 1, price: 89.9 },
    { sku: 'SKU-2', name: 'USB-C Cable', qty: 2, price: 9.9 },
  ],
  total_amount: 109.7,
  paid_amount: 109.7,
  currency: 'EUR',
  payment_status: 'paid',
  status: 'ready_for_shipment',
  demo_scenario: scenario,
};
if (scenario === 'out_of_stock') { order.products[1].qty = 8; order.total_amount = 169.1; order.paid_amount = 169.1; }
if (scenario === 'invalid_status') { order.status = 'cancelled'; }
if (scenario === 'total_mismatch') { order.total_amount = 120; order.paid_amount = 120; }
return [{ json: order }];

const TOLERANCE = 0.01;
return $input.all().map((entry) => {
  const order = entry.json;
  const errors = [];

  // Customer and address
  if (!order.customer || !order.customer.email) errors.push('Missing customer or email');
  const addr = order.shipping_address || {};
  if (!addr.street || !addr.city || !addr.postal_code || !addr.country) errors.push('Incomplete shipping address');

  // 1. Order status: only ready_for_shipment can be shipped
  if (order.status !== 'ready_for_shipment') {
    errors.push('Invalid order status: ' + (order.status || 'missing') + ' (expected ready_for_shipment)');
  }

  // 2. Products
  const products = Array.isArray(order.products) ? order.products : [];
  if (products.length === 0) errors.push('No products in order');
  let computedTotal = 0;
  products.forEach((p, i) => {
    const item = p || {};
    const label = 'Product #' + (i + 1) + (item.sku ? ' (' + item.sku + ')' : '');
    if (!item.sku) errors.push(label + ': missing sku');
    if (!item.name) errors.push(label + ': missing name');
    const qty = Number(item.qty);
    const qtyOk = item.qty !== undefined && item.qty !== null && item.qty !== '' && Number.isFinite(qty) && qty > 0;
    if (!qtyOk) errors.push(label + ': quantity must be greater than 0');
    const price = Number(item.price);
    const priceOk = item.price !== undefined && item.price !== null && item.price !== '' && Number.isFinite(price) && price >= 0;
    if (!priceOk) errors.push(label + ': price must be 0 or more');
    if (qtyOk && priceOk) computedTotal += qty * price;
  });
  computedTotal = Math.round(computedTotal * 100) / 100;

  // 3. Order total = sum(qty x price)
  const total = Number(order.total_amount);
  if (!Number.isFinite(total) || total <= 0) {
    errors.push('Total amount must be greater than 0');
  } else if (Math.abs(computedTotal - total) > TOLERANCE) {
    errors.push('Order total mismatch (computed ' + computedTotal.toFixed(2) + ' vs order ' + total.toFixed(2) + ')');
  }

  // 4. Payment
  if (order.payment_status !== 'paid') errors.push('Payment not completed (payment_status: ' + (order.payment_status || 'missing') + ')');
  if (!order.currency) errors.push('Missing currency');
  if (order.paid_amount !== undefined && order.paid_amount !== null) {
    const paid = Number(order.paid_amount);
    if (!Number.isFinite(paid) || (Number.isFinite(total) && Math.abs(paid - total) > TOLERANCE)) {
      errors.push('Paid amount mismatch (paid ' + order.paid_amount + ' vs total ' + order.total_amount + ')');
    }
  }

  return { json: { ...order, computed_total: computedTotal, isValid: errors.length === 0, validationErrors: errors } };
});

// MOCK list of order IDs already processed (DEMO) — replace with a real lookup later.
const PROCESSED_ORDER_IDS = ['ORD-9999'];
return $input.all().map((entry) => {
  const order = entry.json;
  const duplicate = PROCESSED_ORDER_IDS.includes(order.id);
  const errors = [...(order.validationErrors || [])];
  if (duplicate) errors.push('Duplicate order: ' + order.id + ' was already processed');
  return { json: { ...order, duplicate, validationErrors: errors, isValid: order.isValid === true && !duplicate } };
});

// MOCK hand-off of the validated order to the Inventory & Warehouse process (DEMO).
const order = $json;
const products = (order.products || []).map((p) => ({ sku: p.sku, name: p.name, qty: Number(p.qty) }));
const quantities = {};
products.forEach((p) => { quantities[p.sku] = p.qty; });
return [{ json: {
  order_id: order.id,
  customer: order.customer,
  shipping_address: order.shipping_address,
  products,
  quantities,
  total_amount: order.total_amount,
  currency: order.currency,
  handoff_status: 'sent_to_warehouse',
  sent_at: new Date().toISOString(),
} }];

// MOCK inventory levels (DEMO) — replace with a real inventory lookup later.
const MOCK_STOCK = { 'SKU-1': 10, 'SKU-2': 5 };
const req = $json;
const stockErrors = [];
const stockLines = (req.products || []).map((p) => {
  const known = Object.prototype.hasOwnProperty.call(MOCK_STOCK, p.sku);
  const available = known ? MOCK_STOCK[p.sku] : 0;
  const sufficient = known && p.qty <= available;
  if (!known) stockErrors.push('Unknown SKU in inventory: ' + p.sku);
  else if (!sufficient) stockErrors.push('Insufficient stock for ' + p.sku + ' (requested ' + p.qty + ', available ' + available + ')');
  return { sku: p.sku, name: p.name, requested: p.qty, available, sufficient };
});
return [{ json: { order_id: req.order_id, stockAvailable: stockErrors.length === 0, stockErrors, stockLines } }];

// MOCK stock reservation / deduction (DEMO).
const reservedItems = $json.stockLines.map((l) => ({
  sku: l.sku,
  name: l.name,
  reserved_qty: l.requested,
  stock_before: l.available,
  stock_after: l.available - l.requested,
}));
const remainingStock = {};
reservedItems.forEach((i) => { remainingStock[i.sku] = i.stock_after; });
return [{ json: { order_id: $json.order_id, stockReserved: true, reservation_id: 'RES-' + $json.order_id, reservedItems, remainingStock } }];

// MOCK inventory update after reservation (DEMO).
const updatedItems = $json.reservedItems.map((i) => ({
  sku: i.sku,
  previous_qty: i.stock_before,
  new_qty: i.stock_after,
  change: -i.reserved_qty,
}));
return [{ json: { order_id: $json.order_id, inventoryUpdated: true, updatedItems, updated_at: new Date().toISOString() } }];

// MOCK availability update derived from remaining stock (DEMO).
const productAvailability = $json.updatedItems.map((i) => ({
  sku: i.sku,
  available_qty: i.new_qty,
  availability: i.new_qty > 0 ? 'available' : 'out_of_stock',
}));
return [{ json: { order_id: $json.order_id, availabilityUpdated: true, productAvailability } }];

// MOCK warehouse task creation (DEMO).
// Picking, verification and packaging are PHYSICAL tasks done by warehouse staff, not by n8n.
const handoff = $('Send Order To Inventory & Warehouse').first().json;
return [{ json: {
  warehouse_task_id: 'WH-TASK-001',
  order_id: handoff.order_id,
  products: handoff.products,
  quantities: handoff.quantities,
  shipping_address: handoff.shipping_address,
  status: 'pending',
  human_steps: ['pick products', 'verify products', 'package order'],
  assigned_to: 'Warehouse team',
  created_at: new Date().toISOString(),
} }];

const MAX_CHECKS = 5;
const IN_PROGRESS = ['pending', 'picking', 'verification', 'packaging'];

const task = $('Create Warehouse Task').first().json;
const scenario = $('Get Order').first().json.demo_scenario || 'normal';

const previousCheck = Number($json.warehouse_check_number || 0);
const check = previousCheck + 1;

let status;

if (scenario === 'warehouse_discrepancy') {
  status = 'physical_discrepancy';
}
else if (scenario === 'warehouse_damaged') {
  status = 'damaged';
}
else if (scenario === 'warehouse_missing') {
  status = 'missing';
}
else if (scenario === 'warehouse_stuck') {
  status = IN_PROGRESS[Math.min(check - 1, IN_PROGRESS.length - 1)];

  if (check >= MAX_CHECKS) {
    status = 'warehouse_timeout';
  }
}
else {
  // Normal demo:
  // first check = packaging
  // second check = ready
  status = check === 1 ? 'packaging' : 'ready';
}

return [{
  json: {
    warehouse_task_id: task.warehouse_task_id,
    order_id: task.order_id,
    warehouse_status: status,
    warehouse_check_number: check,
    max_checks: MAX_CHECKS
  }
}];

// MOCK courier create-shipment for demo — replace with a real HTTP Request node later.
return [{ json: {
  shipment_id: 'SHIP-001',
  tracking_number: 'TN123456789',
  carrier: 'Mock Courier',
  status: 'created',
} }];

// MOCK order update (shipped) for demo — replace with a real HTTP Request node later.
const trk = $('Get Tracking Number').item.json;
return [{ json: {
  order_id: $('Get Order').item.json.id,
  status: 'shipped',
  shipment_id: trk.shipment_id,
  tracking_number: trk.tracking_number,
  carrier: trk.carrier,
  ok: true,
} }];

const MAX_CHECKS = 5;

const trk = $('Get Tracking Number').first().json;
const order = $('Get Order').first().json;

// Keep the counter in the workflow data
let previousCheck = Number($json.delivery_check_number || 0);
// The delayed branch passes through a Gmail node (whose output replaces the item),
// so recover the counter from "Update Order Delayed" when it is not in $json.
if (!previousCheck && $('Update Order Delayed').isExecuted) {
  previousCheck = Number($('Update Order Delayed').last().json.delivery_check_number || 0);
}
const check = previousCheck + 1;

let status;

switch (order.demo_scenario || 'normal') {
  case 'delayed':
    status = check === 1 ? 'delayed' : 'delivered';
    break;

  case 'lost':
  case 'damaged':
  case 'failed':
  case 'returned':
    status = order.demo_scenario;
    break;

  case 'unknown_status':
    status = 'held_at_customs';
    break;

  case 'stuck':
    status = 'in_transit';
    break;

  default:
    status = check === 1 ? 'in_transit' : 'delivered';
}

if (
  (status === 'in_transit' || status === 'delayed') &&
  check >= MAX_CHECKS
) {
  status = 'tracking_timeout';
}

const out = {
  shipment_id: trk.shipment_id,
  tracking_number: trk.tracking_number,
  carrier: trk.carrier,
  status,
  delivery_check_number: check,
  max_checks: MAX_CHECKS
};

if (status === 'delivered') {
  out.delivered_at = new Date().toISOString();
}

return [{ json: out }];

const trk = $('Get Tracking Number').item.json;

return [{
  json: {
    order_id: $('Get Order').item.json.id,
    status: 'in_transit',
    shipment_id: trk.shipment_id,
    tracking_number: trk.tracking_number,
    carrier: trk.carrier,
    delivery_check_number: $json.delivery_check_number,
    ok: true
  }
}];

// MOCK order update (delivered) for demo — replace with a real HTTP Request node later.
const trk = $('Get Tracking Number').item.json;
return [{ json: {
  order_id: $('Get Order').item.json.id,
  status: 'delivered',
  shipment_id: trk.shipment_id,
  tracking_number: trk.tracking_number,
  carrier: trk.carrier,
  delivered_at: $json.delivered_at,
  ok: true,
} }];

// DEMO reconciliation against a MOCK payment transaction — replace with a real payment lookup later.
const TOLERANCE = 0.01;
const EXPECTED_CURRENCY = 'EUR';
const order = $('Get Order').first().json;
const scenario = order.demo_scenario || 'normal';
const transaction = {
  transaction_id: 'TXN-' + order.id,
  status: order.payment_status,
  captured_amount: scenario === 'payment_mismatch' ? 99.7 : Number(order.paid_amount),
  currency: order.currency,
};
const total = Number(order.total_amount);
const reasons = [];
if (transaction.status !== 'paid') reasons.push('Payment status is ' + (transaction.status || 'missing') + ' (expected paid)');
if (!Number.isFinite(transaction.captured_amount)) reasons.push('Paid amount missing');
else if (!Number.isFinite(total) || Math.abs(transaction.captured_amount - total) > TOLERANCE) reasons.push('Paid amount ' + transaction.captured_amount.toFixed(2) + ' does not match order total ' + (Number.isFinite(total) ? total.toFixed(2) : 'n/a'));
if (transaction.currency !== EXPECTED_CURRENCY) reasons.push('Currency ' + (transaction.currency || 'missing') + ' (expected ' + EXPECTED_CURRENCY + ')');
const reconciled = reasons.length === 0;
return [{ json: {
  order_id: order.id,
  transaction_id: transaction.transaction_id,
  total_amount: order.total_amount,
  paid_amount: transaction.captured_amount,
  currency: transaction.currency,
  payment_status: transaction.status,
  reconciled,
  discrepancyReason: reconciled ? null : reasons.join('; '),
  note: reconciled ? 'Payment matches delivered order' : 'Payment/transaction inconsistency detected',
} }];

const trk = $('Get Tracking Number').item.json;

return [{
  json: {
    order_id: $('Get Order').item.json.id,
    status: 'delayed',
    shipment_id: trk.shipment_id,
    tracking_number: trk.tracking_number,
    carrier: trk.carrier,
    delivery_check_number: $json.delivery_check_number,
    ok: true
  }
}];

const event=$input.first().json.body||{};
if(!event.order_id && !event.order?.id) return [];
if(event.type && !['order.created','order.validated','order.confirmed','order.cancelled','order.shipped','shipment.updated','payment.reconciled','inventory.reserved','warehouse.ready','warehouse.updated','order.review_required'].includes(event.type))return [];
return [{json:{event,orderId:String(event.order_id||event.order.id),shopBaseUrl:"https://erik-unbarking-foolhardily.ngrok-free.dev",logisticsWebhookUrl:"https://cosmos-team-5ia.app.n8n.cloud/webhook/order-ready-for-shipment"}}];
